package com.shatteredpixel.shatteredpixeldungeon.apd.difficulty;
import java.io.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import com.watabou.utils.Bundle;
import com.shatteredpixel.shatteredpixeldungeon.apd.stats.ProvisionalScoreLookup;
import org.junit.Test;
import static org.junit.Assert.*;
public class CustomRuleMultipliersTest {
 private static final String[] ACTIVE_UPGRADE_SCROLLS_15_TO_60={"1.0","0.9900869420673927","0.9535133402296471","0.9129854091130618","0.8816027193427622","0.8022017576693009","0.7954166047844492","0.7700421127712219","0.7413657033113148","0.7188637668160545","0.6603549492599539","0.6553291630779635","0.6363731084483553","0.6146782669032637","0.5975069938771197","0.5520269436495685","0.5481070012569300","0.5332348272544823","0.5160636579946029","0.5023900462242314","0.4656885169494392","0.4625176038639328","0.4504355133687794","0.4363951427163869","0.4251641621678676","0.3947141351995564","0.3920786461493848","0.3820037796687120","0.3702376806912746","0.3607931636367667","0.3349843655469273","0.3327475100266550","0.3241744721645270","0.3141228762847881","0.3060322758841042","0.2837829908985701","0.2818525332671285","0.2744383885835735","0.2657177928091018","0.2586827426846451","0.2392354572643577","0.2375466159365020","0.2310492806252619","0.2233868537128332","0.2171939182010963","0.20"};
 @Test public void everySuppliedPositionRetainsEveryDecimalDigit()throws Exception{
  int count=0,sliders=0;try(BufferedReader r=new BufferedReader(new InputStreamReader(getClass().getResourceAsStream("/apd/v26r-authoritative.txt"),StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){String[] p=line.split(" \\| ");CustomDungeonRules.Slider s=CustomDungeonRules.Slider.valueOf(p[0]);assertEquals(s.min,Integer.parseInt(p[1]));assertEquals(s.max,Integer.parseInt(p[2]));assertEquals(s.step(),Integer.parseInt(p[3]));String[] values=p[5].split(",");assertEquals((s.max-s.min)/s.step()+1,values.length);for(int i=0;i<values.length;i++){int value=s.min+i*s.step();BigDecimal original=new BigDecimal(values[i]);BigDecimal active=s==CustomDungeonRules.Slider.UPGRADE_SCROLLS&&value>=15?new BigDecimal(ACTIVE_UPGRADE_SCROLLS_15_TO_60[value-15]):original;BigDecimal interim=s==CustomDungeonRules.Slider.UPGRADE_SCROLLS&&value==60?new BigDecimal("0.20"):original;assertEquals(active,CustomRuleMultipliers.individual(s,value));assertEquals(CustomRuleMultipliers.format(active),CustomRulesPresentation.multiplierText(s,value));assertEquals(0,active.compareTo(CustomRuleMultipliers.combined(CustomDungeonRules.defaults().with(s,value))));assertEquals(0,original.compareTo(ProvisionalScoreLookup.combinedForVersion(CustomDungeonRules.defaults().with(s,value).values(),ProvisionalScoreLookup.PREVIOUS_VERSION)));assertEquals(0,interim.compareTo(ProvisionalScoreLookup.combinedForVersion(CustomDungeonRules.defaults().with(s,value).values(),ProvisionalScoreLookup.INTERIM_VERSION)));count++;}sliders++;}}
  assertEquals(18,sliders);assertEquals(357,count);
 }
 @Test public void activeAboveDefaultScrollCurveIsContinuousMonotoneAndAnchored(){
  CustomDungeonRules.Slider scrolls=CustomDungeonRules.Slider.UPGRADE_SCROLLS;
  BigDecimal previous=CustomRuleMultipliers.individual(scrolls,15),maxDrop=BigDecimal.ZERO;
  assertEquals("1.0",previous.toPlainString());
  for(int count=16;count<=60;count++){BigDecimal current=CustomRuleMultipliers.individual(scrolls,count);assertTrue("non-decreasing reward at "+count,previous.compareTo(current)>0);maxDrop=maxDrop.max(previous.subtract(current));previous=current;}
  assertEquals("0.2171939182010963",CustomRuleMultipliers.individual(scrolls,59).toPlainString());
  assertEquals("0.20",CustomRuleMultipliers.individual(scrolls,60).toPlainString());
  assertTrue("curve contains an endpoint cliff: "+maxDrop,maxDrop.compareTo(new BigDecimal("0.081"))<0);
 }
 @Test public void everyNeutralIsExactlyOneAndEveryDisplayHasFourDecimalPlaces(){for(CustomDungeonRules.Slider s:CustomDungeonRules.Slider.values()){assertEquals(0,BigDecimal.ONE.compareTo(CustomRuleMultipliers.individual(s,s.defaultValue())));assertEquals("1.0000×",CustomRulesPresentation.multiplierText(s,s.defaultValue()));}assertEquals(BigDecimal.ONE,CustomRuleMultipliers.combined(CustomDungeonRules.defaults()));}
 @Test public void suppliedEnemyHpExamplesUseTableNotInterpolation(){assertEquals("0.8256×",CustomRulesPresentation.multiplierText(CustomDungeonRules.Slider.ENEMY_HP,50));assertEquals("1.0897×",CustomRulesPresentation.multiplierText(CustomDungeonRules.Slider.ENEMY_HP,125));assertEquals("1.1728×",CustomRulesPresentation.multiplierText(CustomDungeonRules.Slider.ENEMY_HP,150));}
 @Test public void mixedAndBothExtremesUseOrdinaryProductWithoutSquaring(){for(int variant=0;variant<3;variant++){CustomDungeonRules rules=CustomDungeonRules.defaults();BigDecimal expected=BigDecimal.ONE;for(CustomDungeonRules.Slider s:CustomDungeonRules.Slider.values()){int value=variant==0?s.min:variant==1?s.max:(s.ordinal()%2==0?s.min:s.max);rules=rules.with(s,value);expected=expected.multiply(CustomRuleMultipliers.individual(s,value));}assertEquals(0,expected.compareTo(CustomRuleMultipliers.combined(rules)));assertNotEquals(0,expected.multiply(expected).compareTo(CustomRuleMultipliers.combined(rules)));}}
 @Test public void savedRunAuthorityNeverFollowsDraftChanges(){CustomDungeonRules selected=CustomDungeonRules.defaults().with(CustomDungeonRules.Slider.ENEMY_HP,500);CustomScoreSnapshot authority=CustomScoreSnapshot.forNewRun(selected);Bundle b=new Bundle();authority.store(b);CustomDungeonRules draft=selected;for(CustomDungeonRules.Slider s:CustomDungeonRules.Slider.values()){draft=draft.with(s,s.min);assertEquals(authority.multiplierExact,CustomScoreSnapshot.restore(b,selected).multiplierExact);}assertEquals(Long.valueOf(CustomRuleMultipliers.adjusted(99999,CustomRuleMultipliers.combined(selected))),authority.adjustedIdentityScore(99999));}
 @Test public void legacyPendingAndUnknownRunsKeepOriginalEarnedScore(){for(boolean neutral:new boolean[]{false,true}){CustomDungeonRules r=CustomDungeonRules.defaults().with(CustomDungeonRules.Slider.UPGRADE_SCROLLS,neutral?15:60);Bundle outer=new Bundle(),settings=new Bundle();r.store(settings);outer.put("apd_custom_rules",settings);CustomScoreSnapshot.recorded(1,neutral?"NEUTRAL_IDENTITY":"PENDING_CALIBRATION",neutral?"neutral-identity-v1":"pending-calibration-v1",neutral?"1.00":"",r).store(outer);assertEquals(765432,CustomScorePresentation.earnedScore(outer,765432));assertEquals(1,outer.getInt("apd_custom_score_version"));}assertEquals(765432,CustomScorePresentation.earnedScore(new Bundle(),765432));}
 @Test public void extremeScoresUseLongWithoutOverflowAndFormatCompactly(){CustomDungeonRules r=CustomDungeonRules.defaults();for(CustomDungeonRules.Slider s:CustomDungeonRules.Slider.values()){BigDecimal a=CustomRuleMultipliers.individual(s,s.min),b=CustomRuleMultipliers.individual(s,s.max);r=r.with(s,a.compareTo(b)>0?s.min:s.max);}BigDecimal multiplier=CustomRuleMultipliers.combined(r);long score=CustomRuleMultipliers.adjusted(Integer.MAX_VALUE,multiplier);assertTrue(score>Integer.MAX_VALUE);assertTrue(score>0);for(String v:new String[]{"1E-20","1E20","123456789"})assertTrue(CustomRuleMultipliers.format(new BigDecimal(v)).length()<14);}
 @Test public void existingChallengeAndVictoryResultsAreMultipliedExactlyOnce(){for(int challenges=0;challenges<=9;challenges++)for(float win:new float[]{1,2,2.5f}){float challenge=Math.round((float)Math.pow(1.25,challenges)*20f)/20f;int original=(int)(115000*(win*challenge));assertEquals(original,CustomRuleMultipliers.adjusted(original,BigDecimal.ONE));CustomDungeonRules r=CustomDungeonRules.defaults().with(CustomDungeonRules.Slider.ENEMY_HP,500);assertEquals(new BigDecimal("1.9999955905485434").multiply(BigDecimal.valueOf(original)).setScale(0,RoundingMode.HALF_UP).longValueExact(),CustomScoreSnapshot.forNewRun(r).adjustedIdentityScore(original).longValue());}}
}
